        "versionLabel": "Testo vigente — fonte ufficiale della Santa Sede",
        "status": "current",
        "language": "it",
        "text": "§1. Oggetto del giudizio sono:\n1) i diritti di persone fisiche o giuridiche da perseguire o da rivendicare, o fatti giuridici da dichiarare;\n2) i delitti per quanto riguarda l'irrogazione e la dichiarazione della pena.\n§2. Tuttavia le controversie insorte per un atto di potestà amministrativa possono essere deferite solo al Superiore o al tribunale amministrativo.",
