        "status": "current",
        "language": "it",
        "text": "La Chiesa per diritto proprio ed esclusivo giudica:\n1) le cause che riguardano cose spirituali e annesse alle spirituali;\n2) la violazione delle leggi ecclesiastiche e tutto ciò in cui vi è ragione di peccato, per quanto concerne lo stabilirne la colpa ed infliggere pene ecclesiastiche.",
